fn encode_cyclic(s: Vec<i8>) -> Vec<i8> {
    let n = s.len();
    let l = n - (n % 3); // largest multiple of 3 <= n

    let mut out = s.clone();

    // For each full block of 3: [a, b, c] -> [b, c, a]
    for i in (0..l).step_by(3) {
        out[i] = s[i + 1];
        out[i + 1] = s[i + 2];
        out[i + 2] = s[i];
    }

    // Any remaining 1 or 2 elements (n % 3 != 0) stay unchanged due to clone.
    out
}

